#!/usr/bin/env python3
"""Run-queue CLI.

  run <file.py> [name]   freeze the .py and add it to the queue
  run ls                 show the queue
  run rm <id>            remove a queued run (and its snapshot)
  run cancel <id>        cancel a queued run, or kill it if currently running

The worker is launched separately and runs serially on 4 GPUs:
  python worker.py
"""
import os
import sys

import qlib
import snapshot


def cmd_ls():
    entries = qlib.all_entries()
    if not entries:
        print("queue empty")
        return
    print("%-22s %-9s %s" % ("ID", "STATUS", "LOGFILE / SNAPSHOT"))
    for e in entries:
        loc = e.get("logfile") or e["snapshot"]
        extra = ""
        if e["status"] == qlib.FAILED and e.get("exit_code") is not None:
            extra = " (exit %s)" % e["exit_code"]
        print("%-22s %-9s %s%s" % (e["id"], e["status"], loc, extra))


def cmd_rm(eid):
    e = qlib.load(eid)
    if e["status"] == qlib.RUNNING:
        sys.exit("%s is running; use `run cancel %s` first" % (eid, eid))
    snap = os.path.join(qlib.ROOT, e["snapshot"])
    if os.path.exists(snap):
        os.remove(snap)
    os.remove(qlib.entry_path(eid))
    print("removed %s" % eid)


def cmd_cancel(eid):
    e = qlib.load(eid)
    if e["status"] in (qlib.DONE, qlib.FAILED, qlib.CANCELLED):
        sys.exit("%s already %s" % (eid, e["status"]))
    e["cancel_requested"] = True
    qlib.save(e)
    if e["status"] == qlib.RUNNING:
        print("cancel requested; worker will kill %s shortly" % eid)
    else:
        print("%s will be skipped by the worker" % eid)


def main(argv):
    if not argv:
        sys.exit(__doc__)
    cmd = argv[0]
    if cmd == "ls" or cmd == "list":
        cmd_ls()
    elif cmd == "rm":
        cmd_rm(argv[1])
    elif cmd == "cancel":
        cmd_cancel(argv[1])
    elif cmd.endswith(".py"):
        name = argv[1] if len(argv) > 1 else None
        e = snapshot.snapshot_and_enqueue(cmd, name)
        print("queued %s  (snapshot: %s)" % (e["id"], e["snapshot"]))
    else:
        sys.exit("unknown command %r\n%s" % (cmd, __doc__))


if __name__ == "__main__":
    os.chdir(qlib.ROOT)
    main(sys.argv[1:])

